  if (/^https:\/\/[a-zA-Z0-9.-]+(?::[0-9]{1,5})?\/?$/.test(value)) return value.replace(/\/$/, '');
  if ($env.AUTOMATION_ALLOW_LOCAL_HTTP === 'true' && /^http:\/\/(?:localhost|127\.0\.0\.1|host\.docker\.internal)(?::[0-9]{1,5})?\/?$/.test(value)) return value.replace(/\/$/, '');
